INSERT INTO questions (question, options, correct_index, difficulty, category, explanation) VALUES
('Kerala state was formed on which date?', '["1 November 1956","26 January 1950","15 August 1947","1 November 1966"]'::jsonb, 0, 'easy', 'Kerala', 'Kerala was formed on 1 November 1956 under the States Reorganisation Act — celebrated as Kerala Piravi.'),
('How many districts does Kerala have?', '["12","14","15","16"]'::jsonb, 1, 'easy', 'Kerala', 'Kerala has 14 districts, from Thiruvananthapuram in the south to Kasaragod in the north.'),
('International Workers'' Day (May Day) is observed on which date?', '["1 April","1 May","15 May","1 June"]'::jsonb, 1, 'easy', 'Labour', 'May Day, 1 May, honours the struggle of workers everywhere for the eight-hour day and fair conditions.'),
('In which year was the Right to Information Act enacted?', '["2001","2003","2005","2009"]'::jsonb, 2, 'easy', 'Right to Information', 'The RTI Act was enacted in 2005, giving every citizen the right to information held by public authorities.'),
('Under the RTI Act, what is the normal time limit for a reply to an application?', '["7 days","15 days","30 days","60 days"]'::jsonb, 2, 'easy', 'Right to Information', 'The Public Information Officer must reply within 30 days of receiving the application.'),
('The Constitution of India came into force on:', '["15 August 1947","26 November 1949","26 January 1950","2 October 1950"]'::jsonb, 2, 'easy', 'Constitution', 'Adopted on 26 November 1949, the Constitution came into force on 26 January 1950 — Republic Day.'),
('Who chaired the Drafting Committee of the Indian Constitution?', '["Jawaharlal Nehru","Dr. B. R. Ambedkar","Dr. Rajendra Prasad","Sardar Patel"]'::jsonb, 1, 'easy', 'Constitution', 'Dr. B. R. Ambedkar chaired the Drafting Committee and is known as the chief architect of the Constitution.'),
('Most recruitment to Kerala government service is done through:', '["Staff Selection Commission","Kerala Public Service Commission","Employment Exchange only","Union Public Service Commission"]'::jsonb, 1, 'easy', 'Civil service', 'The Kerala PSC conducts recruitment to most posts in Kerala government service, keeping selection transparent and merit-based.'),
('In Kerala government service, ''KSR'' stands for:', '["Kerala State Register","Kerala Service Rules","Kerala Salary Revision","Kerala Staff Regulations"]'::jsonb, 1, 'easy', 'Civil service', 'The Kerala Service Rules (KSR) govern pay, leave, pension and other service conditions.'),
('The Constitution of India opens with the:', '["Fundamental Duties","Preamble","Directive Principles","First Schedule"]'::jsonb, 1, 'easy', 'Constitution', 'The Preamble opens the Constitution: we, the people, resolve to build a sovereign, socialist, secular, democratic republic.'),
('What is the official language of Kerala?', '["Tamil","Kannada","Malayalam","Tulu"]'::jsonb, 2, 'easy', 'Kerala', 'Malayalam is the official language of Kerala, and government work increasingly happens in Malayalam.'),
('Which city is the capital of Kerala?', '["Kochi","Kozhikode","Thrissur","Thiruvananthapuram"]'::jsonb, 3, 'easy', 'Kerala', 'Thiruvananthapuram is the capital, home to the Government Secretariat.'),
('Which Article of the Constitution protects civil servants from dismissal without an inquiry?', '["Article 14","Article 311","Article 356","Article 370"]'::jsonb, 1, 'medium', 'Constitution', 'Article 311 says no civil servant can be dismissed, removed or reduced in rank without an inquiry and a reasonable opportunity to be heard.'),
('Which Article lets the legislature regulate recruitment and conditions of service of government employees?', '["Article 309","Article 300","Article 324","Article 21"]'::jsonb, 0, 'medium', 'Constitution', 'Article 309 is the source of service rules such as the Kerala Service Rules.'),
('Which Article guarantees equality of opportunity in public employment?', '["Article 15","Article 16","Article 19","Article 25"]'::jsonb, 1, 'medium', 'Constitution', 'Article 16 guarantees equal opportunity for all citizens in matters of public employment.'),
('The right to form associations or unions is guaranteed by:', '["Article 19(1)(a)","Article 19(1)(c)","Article 21","Article 32"]'::jsonb, 1, 'medium', 'Constitution', 'Article 19(1)(c) guarantees every citizen the right to form associations or unions.'),
('Fundamental Rights are listed in which Part of the Constitution?', '["Part II","Part III","Part IV","Part IV-A"]'::jsonb, 1, 'medium', 'Constitution', 'Part III (Articles 12–35) lists the Fundamental Rights.'),
('The words ''socialist'' and ''secular'' were added to the Preamble by which amendment?', '["24th Amendment","42nd Amendment","44th Amendment","73rd Amendment"]'::jsonb, 1, 'medium', 'Constitution', 'The 42nd Amendment (1976) added ''socialist'', ''secular'' and ''integrity'' to the Preamble.'),
('The 73rd Constitutional Amendment is about:', '["Municipalities","Panchayati Raj","Anti-defection","Right to Education"]'::jsonb, 1, 'medium', 'Decentralisation', 'The 73rd Amendment (1992) gave constitutional status to Panchayati Raj institutions.'),
('Kerala''s People''s Plan Campaign for decentralised planning was launched in:', '["1987","1991","1996","2002"]'::jsonb, 2, 'medium', 'Decentralisation', 'Launched in 1996, it devolved a large share of plan funds to local bodies, with government employees playing a key role.'),
('Under the RTI Act, a first appeal against a PIO''s decision goes to:', '["The Chief Minister","An officer senior to the PIO","The High Court","The Lokayukta"]'::jsonb, 1, 'medium', 'Right to Information', 'The first appeal lies with the First Appellate Authority, an officer senior in rank to the PIO.'),
('Service disputes of Kerala state government employees are heard by the:', '["Kerala Administrative Tribunal","Consumer Disputes Forum","Lok Adalat only","Central Administrative Tribunal"]'::jsonb, 0, 'medium', 'Civil service', 'The Kerala Administrative Tribunal adjudicates service matters of state government employees.'),
('Who headed Kerala''s first elected ministry in 1957?', '["Pattom Thanu Pillai","R. Sankar","E. M. S. Namboodiripad","C. Achutha Menon"]'::jsonb, 2, 'medium', 'Kerala', 'E. M. S. Namboodiripad led the first ministry of Kerala, formed in April 1957.'),
('Where is the International Labour Organization (ILO) headquartered?', '["New York","Paris","Geneva","Vienna"]'::jsonb, 2, 'medium', 'Labour', 'The ILO, a UN agency for labour rights, is headquartered in Geneva.'),
('Which Part of the Kerala Service Rules deals with pension?', '["Part I","Part II","Part III","Part IV"]'::jsonb, 2, 'hard', 'Civil service', 'KSR Part III contains the pension rules — the ones used when processing pension applications.'),
('In Kerala, the contributory pension scheme applies to employees who joined service on or after:', '["1 January 2004","1 April 2010","1 April 2013","1 April 2016"]'::jsonb, 2, 'hard', 'Civil service', 'Kerala introduced the contributory (National Pension System) scheme for those joining from 1 April 2013.'),
('ILO Convention No. 87 deals with:', '["Minimum wages","Freedom of association and the right to organise","Child labour","Equal remuneration"]'::jsonb, 1, 'hard', 'Labour', 'Convention 87 (1948) protects workers'' freedom of association and their right to organise.'),
('In which year was the International Labour Organization founded?', '["1909","1919","1945","1948"]'::jsonb, 1, 'hard', 'Labour', 'The ILO was founded in 1919, after the First World War, as part of the Treaty of Versailles.'),
('The Haymarket affair, linked to the origin of May Day, took place in which city?', '["London","Chicago","Paris","Manchester"]'::jsonb, 1, 'hard', 'Labour', 'The 1886 Haymarket affair in Chicago grew out of the struggle for the eight-hour working day.'),
('India''s Trade Unions Act was enacted in:', '["1919","1926","1947","1950"]'::jsonb, 1, 'hard', 'Labour', 'The Trade Unions Act, 1926 provided for the registration and protection of trade unions.'),
('Under the RTI Act, information concerning a person''s life or liberty must be given within:', '["24 hours","48 hours","7 days","15 days"]'::jsonb, 1, 'hard', 'Right to Information', 'Section 7(1) requires such information within 48 hours of the request.'),
('Which section of the RTI Act lists exemptions from disclosure?', '["Section 4","Section 6","Section 8","Section 19"]'::jsonb, 2, 'hard', 'Right to Information', 'Section 8 lists the categories of information exempt from disclosure.'),
('Which Article of the Constitution provides for Public Service Commissions for the Union and the States?', '["Article 311","Article 315","Article 320","Article 324"]'::jsonb, 1, 'hard', 'Constitution', 'Article 315 provides for a PSC for the Union and for each State.'),
('How many subjects are listed in the Eleventh Schedule for Panchayats?', '["18","22","29","35"]'::jsonb, 2, 'hard', 'Decentralisation', 'The Eleventh Schedule, added by the 73rd Amendment, lists 29 subjects for Panchayats.'),
('The Kerala Panchayat Raj Act was enacted in:', '["1960","1987","1994","1999"]'::jsonb, 2, 'hard', 'Decentralisation', 'The Kerala Panchayat Raj Act, 1994 followed the 73rd Amendment.'),
('Kerala''s land reforms, abolishing landlordism, took full effect from:', '["1 November 1957","1 January 1970","1 April 1975","26 January 1980"]'::jsonb, 1, 'hard', 'Kerala', 'The amended Kerala Land Reforms Act came into force on 1 January 1970, ending the landlord–tenant system.');
